import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State, Watch } from '@stencil/core';
import { FormDataEvent, SliderThumbSize } from '../../types';

/**
 * @nativeEvent change - dispatched when the value has changed => 'event.target.value' delivers the value of the slider
 *
 * @slot label - named slot 'label', here is any HTML content allowed.
 * @slot description - named slot 'description', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-slider',
  styleUrl: 'slider.scss',
  shadow: true,
})
export class Slider {
  /**
   * minimum value
   */
  @Prop({ reflect: true }) readonly min: number = 0;

  /**
   * maximum value
   */
  @Prop({ reflect: true }) readonly max: number = 100;

  /**
   * size of the thumb
   */
  @Prop({ reflect: true }) readonly thumbSize: SliderThumbSize = 'l';

  /**
   * step size. minimum 0.01
   */
  @Prop({ reflect: true }) readonly step: number = 1;

  /**
   * selected value
   */
  @Prop({ reflect: true, mutable: true }) value: number = this.min;

  /**
   * sets slider to readonly
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * activates tick marks
   */
  @Prop({ reflect: true }) readonly showTickMarks: boolean;

  /**
   * activates marks underneath the bar. will deactivate showTickMarks
   */
  @Prop({ reflect: true }) readonly marks: boolean;

  /**
   * adds a suffix text to the labels, which are activated with the property marks
   */
  @Prop({ reflect: true }) readonly suffix: string = '';

  /**
   * custom value range (numbers only, separated by semicolon)
   * overrides min, max and step
   */
  @Prop({ reflect: true }) readonly customRange: string;

  /**
   * activates tooltip on drag
   */
  @Prop({ reflect: true }) readonly showDragTooltip: boolean;

  /**
   * custom template for displaying the current value.
   * Use '{value}' as a placeholder, i.e. '{value}%' for 50%
   */
  @Prop({ reflect: true }) readonly valueTemplate: string;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @State() private isDragged: boolean = false;

  private displayedValue: number;

  @Element() host: HTMLElement;

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (this.disabled) return;

    if (event.code === 'ArrowLeft' || event.code === 'ArrowDown') {
      this.value = this.decreaseOneStep();
      event.preventDefault();
      return;
    }
    if (event.code === 'ArrowRight' || event.code === 'ArrowUp') {
      this.value = this.increaseOneStep();
      event.preventDefault();
      return;
    }
    if (event.code === 'Home') {
      this.value = this.getMinimum();
      event.preventDefault();
      return;
    }
    if (event.code === 'End') {
      this.value = this.getMaximum();
      event.preventDefault();
    }
  }

  @Listen('mousedown')
  onDragStart(e) {
    if (this.disabled) return;

    if (this.isThumbPressed(e)) {
      this.isDragged = true;
      return;
    }

    if (this.isTrackPressed(e)) {
      this.onSliderMoved(e);
      this.isDragged = true;
    }
  }

  @Listen('mouseup', { target: 'window' })
  onDragEnd() {
    this.isDragged = false;
  }

  @Listen('mousemove', { target: 'window' })
  onDrag(e) {
    if (!this.isDragged) return;
    this.onSliderMoved(e);
  }

  @Watch('isDragged')
  onDraggedChanged() {
    if (this.isDragged) {
      if (this.showDragTooltip) this.showTooltip();
    } else {
      this.hideTooltip();
    }
  }

  @Watch('value')
  onValueChanged() {
    this.displayValue();

    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
  }

  componentDidLoad() {
    this.displayValue();
    this.addFormsHandling();
    this.addAriaLabel();
    this.groupuiDidLoad.emit();
  }

  private addAriaLabel() {
    if (this.isLabelSlotProvided()) {
      if (!this.host.hasAttribute('aria-label')) {
        this.host.setAttribute('aria-label', this.getSlotContent('label'));
      }
    }
  }

  private decreaseOneStep(): number {
    return this.constrained(this.rounded(this.value - this.step));
  }

  private increaseOneStep(): number {
    return this.constrained(this.rounded(this.value + this.step));
  }

  private getMinimum(): number {
    if (this.customRange) return this.parseCustomRange()[0];
    return this.min;
  }

  private getMaximum(): number {
    if (this.customRange) return this.parseCustomRange().pop();
    return this.max;
  }

  private parseCustomRange(): number[] {
    if (!this.customRange) return [];
    return this.customRange
      .split(';')
      .map((element) => Number(element.trim()))
      .filter((element) => !isNaN(element));
  }

  private isTrackPressed(e) {
    return e.composedPath().includes(this.track());
  }

  private isThumbPressed(e) {
    return e.composedPath().includes(this.thumb());
  }

  private hideTooltip() {
    this.tooltip().style.opacity = '0';
  }

  private showTooltip() {
    this.tooltip().style.opacity = '1';
  }

  private displayValue() {
    this.displayedValue = this.constrained(this.value);
    this.moveThumb();
    this.moveTooltip();
    this.adjustFill();
  }

  private moveThumb() {
    const thumb = this.thumb();
    if (!thumb) return;
    thumb.style.left = `${this.fillPercentage()}%`;
  }

  private moveTooltip() {
    const tooltip = this.tooltip();
    if (!tooltip) return;
    tooltip.style.left = `${this.fillPercentage()}%`;
  }

  private adjustFill() {
    const fill = this.fill();
    if (!fill) return;
    fill.style.right = `${100 - this.fillPercentage()}%`;
  }

  private constrained(value: number): number {
    return Math.max(this.getMinimum(), Math.min(this.getMaximum(), value));
  }

  private rounded(value: number): number {
    return Math.round((value + Number.EPSILON) * 100) / 100;
  }

  private onSliderMoved(event) {
    this.value = this.constrained(this.rounded(this.roundToNearestStep(this.trackPositionToValue(event.clientX))));
  }

  private roundToNearestStep(value: number): number {
    if (this.step === 0) return value;
    if (this.customRange) {
      let smallestDifference = Infinity;
      let closestStep = 0;
      this.parseCustomRange().forEach((step) => {
        if (Math.abs(value - step) < smallestDifference) {
          smallestDifference = Math.abs(value - step);
          closestStep = step;
        }
      });
      return closestStep;
    }
    return Math.round(value / this.step) * this.step;
  }

  private trackPositionToValue(pos: number) {
    const ratioOfPosition = this.fillRatio(pos);
    if (this.customRange) {
      const range = this.parseCustomRange();
      for (let i = 0; i < range.length; i++) {
        const startPercentage = i / (range.length - 1);
        const endPercentage = (i + 1) / (range.length - 1);
        if (ratioOfPosition > 1) return this.getMaximum();
        if (startPercentage <= ratioOfPosition && endPercentage >= ratioOfPosition) {
          const relativeRatio = (ratioOfPosition - startPercentage) / (endPercentage - startPercentage);
          return (range[i + 1] - range[i]) * relativeRatio + range[i];
        }
      }
    }
    return (this.max - this.min) * ratioOfPosition + this.min;
  }

  private fillRatio(clampedPosition: number): number {
    const track = this.track();
    if (!track) return 0;
    return (
      (clampedPosition - track.getBoundingClientRect().left) /
      (track.getBoundingClientRect().right - track.getBoundingClientRect().left)
    );
  }

  private fillPercentage(): number {
    return this.percentageOnTrack(this.displayedValue);
  }

  private percentageOnTrack(value: number): number {
    if (this.customRange) {
      const range = this.parseCustomRange();
      return (range.indexOf(value) / (range.length - 1)) * 100;
    }
    return ((value - this.min) / (this.max - this.min)) * 100;
  }

  private getSlotContent(slotName: string): string {
    const slot = this.host.querySelector(`[slot="${slotName}"]`);
    return slot?.innerHTML;
  }

  private addFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value.toString());
    });
  }

  private tooltip(): HTMLElement | null {
    return this.host.shadowRoot.querySelector('.tooltip');
  }

  private thumb(): HTMLElement | null {
    return this.host.shadowRoot.querySelector('.thumb');
  }

  private track(): HTMLElement | null {
    return this.host.shadowRoot.querySelector('.track');
  }

  private fill(): HTMLElement | null {
    return this.host.shadowRoot.querySelector('.fill');
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private tickMarkCount(): number {
    if (this.step === 0) return 0;
    if (!this.showTickMarks && !this.marks) return 0;
    if (this.customRange) return this.parseCustomRange().length - 1;
    return (this.max - this.min) / this.step;
  }

  private tickMarks(): HTMLElement[] {
    const tickMarks = [];
    for (let i = 1; i < this.tickMarkCount(); i++) {
      const position = this.getTickPosition(i);
      const tickMark: HTMLElement = (
        <div class="tick-mark" data-value={i * this.step} style={{ left: `${position.percentage}%` }} />
      );
      tickMarks.push(tickMark);
    }
    return tickMarks;
  }

  private markers(): HTMLElement[] {
    const markers = [];
    for (let i = 0; i <= this.tickMarkCount(); i++) {
      const { nearestStep, percentage } = this.getTickPosition(i);
      markers.push(<div class="mark" data-value={i * this.step} style={{ left: `${percentage}%` }} />);
      markers.push(
        <div class="label" data-value={i * this.step} style={{ left: `${percentage}%` }}>
          {nearestStep}
          {this.suffix}
        </div>
      );
    }
    return markers;
  }

  private getTickPosition(i: number): { nearestStep: number; percentage: number } {
    const range = this.parseCustomRange();
    let nearestStep: number;
    let percentage: number;

    if (this.customRange) {
      nearestStep = range[i];
      percentage = (i / (range.length - 1)) * 100;
    } else {
      nearestStep = this.roundToNearestStep(this.getMinimum() + this.step * i);
      percentage = this.percentageOnTrack(nearestStep);
    }
    return { nearestStep, percentage };
  }

  private getAriaValueText(): string {
    let currentValue = this.value.toString();
    if (this.marks && this.suffix) currentValue += this.suffix;
    return currentValue;
  }

  private isTopInfoAvailable() {
    return this.isLabelSlotProvided() || this.valueTemplate;
  }

  private filledValueTemplate() {
    return this.valueTemplate.replace('{value}', this.value.toLocaleString(Slider.browserLanguage()));
  }

  private static browserLanguage(): string {
    return window.navigator.language?.slice(0, 2);
  }

  render() {
    return (
      <Host
        role="slider"
        aria-valuemin={this.getMinimum()}
        aria-valuemax={this.getMaximum()}
        aria-valuetext={this.getAriaValueText()}
        tabIndex={this.disabled ? -1 : 0}
      >
        {this.isTopInfoAvailable() && (
          <div class="top-info" aria-hidden="true">
            {this.isLabelSlotProvided() && (
              <label class="label" id="label">
                <slot name="label" />
              </label>
            )}
            {this.valueTemplate && <div class="value">{this.filledValueTemplate()}</div>}
          </div>
        )}
        <div class="track">
          <div class="bar">
            {this.showTickMarks && !this.marks && this.tickMarks()}
            <div class="fill"></div>
            <div class="thumb" title="slider"></div>
            <div class="tooltip">
              <span>{this.value.toString() + this.suffix}</span>
            </div>
            {this.marks && this.markers()}
          </div>
        </div>
        {this.isDescriptionSlotProvided() && (
          <div class={{ description: true, 'with-marks': this.marks }} aria-hidden="true">
            <slot name="description" />
          </div>
        )}
      </Host>
    );
  }
}
